package com.franco.desco.adapter.in.web.campaignparticipant;import com.franco.desco.application.campaignparticipant.*;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.campaignparticipant.CampaignParticipantModels;import org.springframework.stereotype.Component;
@Component public class CampaignParticipantWebMapper{public CampaignParticipantCommands.ListParticipants list(int p,int t,Long camp,String estado){return new CampaignParticipantCommands.ListParticipants(new PageRequest<>(p,t,new CampaignParticipantCommands.Filter(camp,estado),null,null));}public CampaignParticipantResponses.Summary response(CampaignParticipantModels.Summary x){return new CampaignParticipantResponses.Summary(x.participacionId(),x.campaniaVentaId(),x.estadoParticipacion(),x.fechaRegistro(),x.socioId(),x.numeroDocumento(),x.socioNombre(),x.operativos(),x.entregasConfirmadas());}public CampaignParticipantResponses.Detail response(CampaignParticipantModels.Detail x){return new CampaignParticipantResponses.Detail(x.participacionId(),x.estadoParticipacion(),x.fechaRegistro(),x.campaniaVentaId(),x.campania(),x.socioId(),x.numeroDocumento(),x.socioNombre(),x.operativos().stream().map(o->new CampaignParticipantResponses.Operation(o.operativoSocioId(),o.operativoVentaId(),o.codigo(),o.estadoOperativo(),o.estadoParticipacion())).toList(),x.entregas().stream().map(d->new CampaignParticipantResponses.Delivery(d.entregaSocioId(),d.codigoLote(),d.fechaHora(),d.pesoAceptadoKg(),d.estadoControlCalidad(),d.estadoProceso())).toList());}}
